  1	/**
  2	 * The `build` stage: run the lane's own build script against the lane's own
  3	 * generated configuration.
  4	 *
  5	 * The build path for the applications already completed is not in the operator
  6	 * flow at all — `packages/cli/src/fixture/react-hospitalrun-vite8-run.ts` runs
  7	 * the *workspace's* Vite binary against a *workspace* configuration file, and
  8	 * that file imports the frozen adapter by source path. The lane is never
  9	 * self-contained in that arrangement, and nothing an operator can run
 10	 * reproduces it.
 11	 *
 12	 * This stage runs the script the lane's own rewritten manifest declares, from
 13	 * the lane, resolving the build tool out of the lane's own installed closure.
 14	 * The one thing the lane still reaches into this workspace for is the frozen
 15	 * adapter source, exactly as the fixture configurations do. Making the lane
 16	 * resolve a published `@versionless/react` instead is a packaging decision this
 17	 * stage deliberately does not take, and the record says so rather than leaving
 18	 * a reader to discover it from the import specifier.
 19	 *
 20	 * A non-zero exit from the build is a **defect**, not a refusal.
 21	 */
 22	
 23	import { execFile } from 'node:child_process';
 24	import { readdir } from 'node:fs/promises';
 25	import { promisify } from 'node:util';
 26	import * as path from 'pathe';
 27	import { directoryExists, readJsonFile } from './analyze.ts';
 28	import { LANE_BUILD_DIRECTORY } from './lane.ts';
 29	import { refuse } from './refusals.ts';
 30	
 31	const run = promisify(execFile);
 32	
 33	const BUILD_NOT_ESTABLISHED: readonly string[] = Object.freeze([
 34		'A completed build establishes that the lane emitted output. It is not a browser proof, a parity reading, or a witness pass; nothing here establishes that the emitted bundle behaves as the application did on its era toolchain.',
 35		'The lane resolves the frozen adapter from this workspace by relative path, so this build is reproducible by this pipeline in this checkout. It does not establish that the lane builds anywhere else.',
 36		'`outputFiles` counts files below the build directory. It is a count, not a comparison against any previous build.',
 37	]);
 38	
 39	export type BuildPlan = Readonly<{
 40		command: readonly string[];
 41		script: string;
 42		configuration: string;
 43		outDirectory: string;
 44	}>;
 45	
 46	/** Decide the build command for a lane, or refuse by name. */
 47	export async function planLaneBuild(
 48		laneDir: string,
 49		configuration = 'vite.config.ts',
 50	): Promise<BuildPlan> {
 51		if (!(await directoryExists(path.join(laneDir, 'node_modules'))))
 52			refuse({
 53				code: 'build.lane-closure-absent',
 54				message:
 55					'Build: the lane carries no node_modules, so the build tool its manifest declares is not resolvable from the lane. Run the install stage first rather than have this stage build against the workspace closure instead of the lane closure.',
 56				stage: 'build',
 57				origin: 'pipeline',
 58			});
 59		const manifest = await readJsonFile(path.join(laneDir, 'package.json'));
 60		const scripts = (manifest?.scripts ?? {}) as Record<string, string>;
 61		const script = scripts.build;
 62		if (typeof script !== 'string' || script.trim() === '')
 63			refuse({
 64				code: 'build.no-build-script',
 65				message:
 66					"Build: the lane's package.json declares no build script, so there is no command to run. The lane composition rewrites that script; a lane without one was not composed by this flow.",
 67				stage: 'build',
 68				origin: 'pipeline',
 69			});
 70		if (!(await fileInLane(laneDir, configuration)))
 71			refuse({
 72				code: 'build.configuration-absent',
 73				message: `Build: the lane carries no ${configuration}, so the generated build configuration this stage runs against is missing. The lane composition writes it; a lane without one was not composed by this flow.`,
 74				stage: 'build',
 75				origin: 'pipeline',
 76			});
 77		return Object.freeze({
 78			command: Object.freeze(['npm', 'run', 'build']),
 79			script,
 80			configuration,
 81			outDirectory: LANE_BUILD_DIRECTORY,
 82		});
 83	}
 84	
 85	async function fileInLane(laneDir: string, file: string): Promise<boolean> {
 86		try {
 87			return (await readdir(laneDir)).includes(file);
 88		} catch {
 89			return false;
 90		}
 91	}
 92	
 93	async function countFilesBelow(directory: string): Promise<number> {
 94		if (!(await directoryExists(directory))) return 0;
 95		let count = 0;
 96		for (const entry of await readdir(directory, { withFileTypes: true })) {
 97			if (entry.isDirectory()) {
 98				count += await countFilesBelow(path.join(directory, entry.name));
 99				continue;
100			}
101			if (entry.isFile()) count += 1;
102		}
103		return count;
104	}
105	
106	export type BuildRecord = Readonly<{
107		stage: 'build';
108		ran: boolean;
109		reason: string | null;
110		command: readonly string[] | null;
111		script: string | null;
112		configuration: string | null;
113		outDirectory: string | null;
114		exitCode: number | null;
115		outputFiles: number | null;
116		notEstablished: readonly string[];
117	}>;
118	
119	/** The record for a stage the run did not ask for. */
120	export function buildNotRequested(reason: string): BuildRecord {
121		return Object.freeze({
122			stage: 'build',
123			ran: false,
124			reason,
125			command: null,
126			script: null,
127			configuration: null,
128			outDirectory: null,
129			exitCode: null,
130			outputFiles: null,
131			notEstablished: BUILD_NOT_ESTABLISHED,
132		});
133	}
134	
135	/** Run the build this stage planned. A non-zero exit is a defect. */
136	export async function runLaneBuild(
137		laneDir: string,
138		configuration = 'vite.config.ts',
139		environment: NodeJS.ProcessEnv = process.env,
140	): Promise<BuildRecord> {
141		const plan = await planLaneBuild(laneDir, configuration);
142		const [binary, ...args] = plan.command as readonly [string, ...string[]];
143		try {
144			await run(binary, args, { cwd: laneDir, env: environment, maxBuffer: 64 * 1024 * 1024 });
145		} catch (error) {
146			const detail = error instanceof Error ? error.message : String(error);
147			throw new Error(
148				`build: ${plan.command.join(' ')} failed in the lane. This is a defect rather than a refusal: the lane was composed and installed and the build still did not complete. ${detail}`,
149			);
150		}
151		return Object.freeze({
152			stage: 'build',
153			ran: true,
154			reason: null,
155			command: plan.command,
156			script: plan.script,
157			configuration: plan.configuration,
158			outDirectory: plan.outDirectory,
159			exitCode: 0,
160			outputFiles: await countFilesBelow(path.join(laneDir, plan.outDirectory)),
161			notEstablished: BUILD_NOT_ESTABLISHED,
162		});
163	}

